import{a as e,i as t,n,o as r,r as i,s as a,t as o}from"./Layout-B1P81BZW.js";var s=e(),c=a(r(),1),l=t(),u=`1QdqLp4riClyC4h7HTQwxoch-Bj31Fa2D`,d=e=>`https://drive.google.com/file/d/${e}/view`,f=(e,t=1400)=>`https://drive.google.com/thumbnail?id=${e}&sz=w${t}`,p=[`Easily learns new skills and work methods`,`Has proper systems of record-keeping`,`Understands product categories and market knowledge`,`Has marketing & graphic ability — online ads and product images`,`Strong coordination with internal and external teams`,`Strong character and abstains from drugs`,`Good communicator — effective in negotiation to serve the business`];function m(){return(0,l.jsxs)(n,{active:`warehouse`,title:`Warehouse & logistics — Kaung Myat Thu`,description:`I was Warehouse Supervisor at NPT Group (6 Jan – 1 Nov 2024), and later set up the POS and shelf map for a car-parts shop as a freelance project.`,children:[(0,l.jsx)(i,{num:`02`,kicker:`Warehouse · NPT Group + freelance CSM`,title:`Keeping stock visible — and right.`,sub:`Two things I did on different timelines — Warehouse Supervisor at NPT Group through 2024, then a POS and shelf map for a car-parts shop.`}),(0,l.jsxs)(`div`,{className:`overview-card`,children:[(0,l.jsx)(`div`,{className:`overview-kicker`,children:`Overview`}),(0,l.jsx)(`h3`,{children:`One job, and one freelance project after it.`}),(0,l.jsxs)(`p`,{children:[(0,l.jsx)(`b`,{children:`NPT Group`}),` was a job I held: Warehouse Supervisor, `,(0,l.jsx)(`b`,{children:`6 January – 1 November 2024`}),`. `,(0,l.jsx)(`b`,{children:`CSM`}),` came after it, a freelance project of about four and a half months. I never had fixed dates for that one, so I do not give any.`]}),(0,l.jsx)(`p`,{children:`Both are about stock; the work underneath was not the same. At NPT I kept the inventory record by hand. At CSM there was no till system at all, so I registered the stock into a POS-ready Excel register, gave every part a location, mapped the shop and trained the staff on a till mock-up.`})]}),(0,l.jsxs)(`div`,{className:`panel`,children:[(0,l.jsx)(`h4`,{children:`NPT Group · Warehouse Supervisor — 6 Jan 2024 → 1 Nov 2024`}),(0,l.jsxs)(`p`,{style:{margin:`0 0 14px`},children:[`Family-shared distributor — electronics / tools (hand tools, power tools, chainsaws, grinders) and raw material (nails, tape, glue, pipes, valves, bars, bathroom accessories). There was no stock system in place, so every item was registered by hand every day. Sign-off: co-founder letter of recommendation dated `,(0,l.jsx)(`b`,{children:`08 Dec 2024`}),`.`]}),(0,l.jsx)(`ul`,{className:`ai-reader-list`,style:{margin:`0 0 14px`},children:p.map(e=>(0,l.jsx)(`li`,{children:e},e))}),(0,l.jsxs)(`figure`,{style:{margin:`18px 0 0`},children:[(0,l.jsx)(`a`,{href:d(u),target:`_blank`,rel:`noopener`,children:(0,l.jsx)(`img`,{src:f(u,1400),alt:`NPT Group reference letter`,loading:`lazy`,style:{width:`100%`,height:`auto`,borderRadius:12,border:`1px solid #dbe3ec`,display:`block`}})}),(0,l.jsxs)(`figcaption`,{className:`muted`,style:{fontSize:`.8rem`,margin:`8px 0 0`},children:[`My reference letter from NPT Group's co-founder, dated 08 Dec 2024. `,(0,l.jsx)(`a`,{href:d(u),target:`_blank`,rel:`noopener`,children:`Open full size ↗`})]})]}),(0,l.jsxs)(`div`,{className:`note-box`,children:[(0,l.jsx)(`svg`,{viewBox:`0 0 24 24`,children:(0,l.jsx)(`path`,{d:`M12 9v5m0 4h.01m10-5a10 10 0 10-20 0 10 10 0 0020 0z`})}),(0,l.jsx)(`span`,{children:`The working notes are mine; the letter is NPT’s.`})]})]}),(0,l.jsxs)(`div`,{className:`panel`,id:`csm`,children:[(0,l.jsxs)(`h4`,{children:[`CSM · ချစ်စုမ, the car-parts shop — POS setup, shelf map, staff training `,(0,l.jsx)(`span`,{className:`muted`,style:{fontWeight:400},children:`(freelance, about four and a half months)`})]}),(0,l.jsxs)(`p`,{className:`muted`,style:{fontSize:`.82rem`,margin:`0 0 12px`},children:[`CSM is short for ချစ်စုမ — `,(0,l.jsx)(`a`,{href:`https://maps.app.goo.gl/ZC7WVxtcdegZSvyJ8`,target:`_blank`,rel:`noopener`,children:`the shop on Google Maps ↗`})]}),(0,l.jsx)(`p`,{style:{margin:`0 0 12px`},children:`The shop had no till system. To know what was in stock I needed a POS, and to run a POS I needed the stock registered. Neither existed, and neither could be built without the other. I heard about it through a friend whose family knew the shop, went in to look, and stayed four and a half months.`}),(0,l.jsx)(`p`,{style:{margin:`0 0 12px`},children:`The setup does not start inside the software. Almost every local POS imports from Excel, so I built the register in that shape: one row per item, with its code, its ID and the columns that separate one part from the next. I did not know car parts. I asked the owners how the parts differ — brand, vehicle family, model, the packaging — and built the columns from their answers: category, code, short name, brand, family, model, package colour, description, shelf location, quantity, one tab per category of part. Most of the work sat there, taking what the shop knew and writing it as a table the POS could import.`}),(0,l.jsxs)(`p`,{style:{margin:`0 0 12px`},children:[`The number printed on the box does not identify the part. Sometimes it is the manufacturer’s number, sometimes the distributor’s tag, and on repackaged stock it can be missing or wrong. So I gave every item an ID of its own — `,(0,l.jsx)(`code`,{children:`BP`}),` for brake pads, `,(0,l.jsx)(`code`,{children:`WP`}),` for water pumps, `,(0,l.jsx)(`code`,{children:`P-F`}),` for fuel pumps — and kept the vendor number beside it as a reference, never as the key. The same ID set in a barcode font prints as the label, so the shelf, the sheet and the scanner carry one value.`]}),(0,l.jsx)(`p`,{style:{margin:`0 0 12px`},children:`The owners are older men, careful with what they know, and they did not want their stock relocated: when a customer asks for a part they walk straight to it. So I mapped the shop as it stood, and left moving the shelves for them to ask for.`}),(0,l.jsx)(`p`,{style:{margin:`0 0 12px`},children:`The space is the part that is hard to put on a page. The brake pads live on four standing shelf runs. A row is no longer than five feet, no wider than a foot and a half, and there is under two feet of clearance to the shelf above. The shelf itself does not divide that neatly. Where a run has a leg at mid-span, the leg blocks the middle of the shelf, so the run is written as two rows, one either side of it. A row in the sheet is a stretch of shelf, not a shelf. The brake pads alone are 389 numbered rows in the stock file. The first fifty-one of them carry eighteen part shapes under fifty-one labels: D-2252 takes eight, D-2239 seven, D-2222 five. Some of those eight are the same brand written twice, jet and JET, and kevlar appears twice in the same block.`}),(0,l.jsx)(`p`,{style:{margin:`0 0 16px`},children:`One code is one shape, not one part. D-2212 carries three labels in this sheet: Sun rise, sure, Golden Star. The stock file has a Family column, sitting between Brand and Model, for the group a row belongs to. The brake-pad sheet does not have that column — it runs from Brand straight to Description — so the family rides in the code instead: D-2183 and D-2183-M, D-1250 and D-1250-M, D-2198 and D-2198-M. The number says what the pad fits, the letters after it say which variant, and the brand says who sells it.`}),(0,l.jsx)(`p`,{style:{margin:`0 0 16px`},children:`The Family column is where that join was meant to happen. It holds the other brand's code for the same part. A Paraut water pump sells as S3-024 and carries Gws-34 beside it, Genteq's Gwp-50117 carries Gwho-47, and on the filter sheet a KYIOI filter sells as 23303-54071 with BF-113 in the family cell, a DMAX one as MD-069782 with C-1008. Two codes, one filter, and nothing else on the row saying so. The brake-pad sheet has no such column, so its variants sat unjoined.`}),(0,l.jsxs)(`div`,{style:{margin:`0 0 16px`,border:`1px solid #dbe3ec`,borderRadius:12,overflow:`hidden`},children:[(0,l.jsx)(`div`,{style:{padding:`10px 14px`,background:`#f7f9fb`,borderBottom:`1px solid #dbe3ec`,fontSize:`.72rem`,letterSpacing:`.14em`,textTransform:`uppercase`,color:`#8b96a6`},children:`Break-pad sheet — D-2239 and D-2252, as the shop wrote them`}),(0,l.jsx)(`div`,{style:{maxHeight:300,overflowY:`auto`},children:(0,l.jsxs)(`table`,{className:`mini-table`,style:{margin:0},children:[(0,l.jsx)(`thead`,{children:(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`th`,{style:{width:`45%`},children:`Shorthand`}),(0,l.jsx)(`th`,{children:`Brand`})]})}),(0,l.jsxs)(`tbody`,{children:[(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`D-2239`}),(0,l.jsx)(`td`,{children:`kevelar`})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`D-2239`}),(0,l.jsx)(`td`,{children:`JNBK`})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`D-2239`}),(0,l.jsx)(`td`,{children:`MK`})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`D-2239`}),(0,l.jsx)(`td`,{children:`JNBK`})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`D-2239`}),(0,l.jsx)(`td`,{children:`Hoku`})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`D-2239`}),(0,l.jsx)(`td`,{children:`WKT`})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`D-2239`}),(0,l.jsx)(`td`,{children:`Paraut`})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`D-2252`}),(0,l.jsx)(`td`,{children:`jnbk`})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`D-2252`}),(0,l.jsx)(`td`,{children:`kevlar`})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`D-2252`}),(0,l.jsx)(`td`,{children:`jet`})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`D-2252`}),(0,l.jsx)(`td`,{children:`paraut`})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`D-2252`}),(0,l.jsx)(`td`,{children:`JET`})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`D-2252`}),(0,l.jsx)(`td`,{children:`kevlar`})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`D-2252`}),(0,l.jsx)(`td`,{})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`D-2252`}),(0,l.jsx)(`td`,{children:`nibk`})]})]})]})}),(0,l.jsx)(`p`,{className:`muted`,style:{fontSize:`.78rem`,margin:`10px 14px 12px`},children:`Fifteen lines from that sheet, copied as written. Two shapes, five brands each way, and one blank the shop had not filled. Those fifteen had to land on four runs, split at each leg, and the map had to hold while the stock moved.`})]}),(0,l.jsx)(`p`,{style:{margin:`0 0 12px`},children:`I was on a time-based arrangement, not fixed hours: no check-in, no check-out. The one rule was to tell them when I was not coming, so they would not count me for lunch. The stock turned over between my visits. Some days I arrived at ten, some days at one, and by then new stock had come in, items I had registered had sold, and the codes I had prepared for them no longer matched the shelf. A warehouse this size changes all day, and most lines carry thirty pieces at most. Registering the same shelf a second time would have taken the whole project.`}),(0,l.jsx)(`p`,{style:{margin:`0 0 12px`},children:`So I split it. They would do the ground stock count themselves once registration was complete, and I kept the mapping and the codes, explained them and walked the staff through them, so that new stock could be placed without me walking the aisle again. They scoped it at three months. I delivered in four and a half.`}),(0,l.jsx)(`p`,{style:{margin:`0 0 12px`},children:`When the register was finished I built the map over it: position codes, a searchable index, a written guide to picking and replenishment. Then the till mock-up: item codes, scanning, a receipt, the stock line moving when a sale goes through, and a training session with the store staff. What the shop still has to add is the ground count in the sheet. After that it is one import.`}),(0,l.jsx)(`p`,{style:{margin:`0 0 14px`},children:`The setup is mine: the register, the codes, the IDs, the columns the POS reads and the map underneath them. The one step I did not take was pressing import, which had to wait for their count, and the software is the shop’s, not mine.`}),(0,l.jsxs)(`table`,{className:`mini-table`,style:{margin:`4px 0 16px`},children:[(0,l.jsx)(`thead`,{children:(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`th`,{children:`What the map holds`}),(0,l.jsx)(`th`,{children:`Sheets`})]})}),(0,l.jsxs)(`tbody`,{children:[(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`Shelf Map Guide, Shelf Location Index, Shelf Map Review`}),(0,l.jsx)(`td`,{children:`3`})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`Category stock records — water pump, brake pad, CV joint, brake/clutch, belt, fuel pump, joint, ground pump, ground rope, stock setup`}),(0,l.jsx)(`td`,{children:`11`})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`KMT-brand records — brake, filter, pump, oil, belt, joint, utility`}),(0,l.jsx)(`td`,{children:`7`})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsxs)(`td`,{children:[`Shelf-map sheets, one per rack and shelf (`,(0,l.jsx)(`code`,{children:`MR-1-SH-1`}),`, `,(0,l.jsx)(`code`,{children:`MR-1-SH-2`}),`, `,(0,l.jsx)(`code`,{children:`MR-2-SH-1`}),`, `,(0,l.jsx)(`code`,{children:`SH-3`}),`)`]}),(0,l.jsx)(`td`,{children:`7`})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`Category update records — the same categories, revised`}),(0,l.jsx)(`td`,{children:`8`})]}),(0,l.jsxs)(`tr`,{children:[(0,l.jsx)(`td`,{children:`Contents`}),(0,l.jsx)(`td`,{children:`1`})]})]})]}),(0,l.jsxs)(`div`,{className:`dl-row`,children:[(0,l.jsxs)(`a`,{className:`btn-dl btn-dark`,href:`https://drive.google.com/file/d/10XOAv-I7ROVnqFqA8jomVxnuDPe1q93F/view`,target:`_blank`,rel:`noopener`,children:[(0,l.jsx)(`svg`,{viewBox:`0 0 24 24`,children:(0,l.jsx)(`path`,{d:`M12 3v12m0 0l-4.5-4.5M12 15l4.5-4.5M4 19h16`})}),`CSM shelf-map master · XLSX`]}),(0,l.jsxs)(`a`,{className:`btn-dl btn-dark`,href:`https://drive.google.com/file/d/1gvdPV9ZSIcRrEmkzuLp4Lqzx6Wxwnt1D/view`,target:`_blank`,rel:`noopener`,children:[(0,l.jsx)(`svg`,{viewBox:`0 0 24 24`,children:(0,l.jsx)(`path`,{d:`M12 3v12m0 0l-4.5-4.5M12 15l4.5-4.5M4 19h16`})}),`Till mock-up — the one I trained the staff on · XLSM`]})]}),(0,l.jsx)(`p`,{className:`muted`,style:{fontSize:`.82rem`,margin:`12px 2px 0`},children:`The till file runs on test stock and test prices — it was built to train the staff, not to hold shop data.`})]}),(0,l.jsxs)(`div`,{className:`takeaway`,children:[(0,l.jsx)(`span`,{className:`ti`,children:`◆`}),(0,l.jsxs)(`p`,{children:[(0,l.jsx)(`span`,{className:`label`,children:`What this demonstrates`}),`Breaking a shop out of the no-till/no-stock circle: building the POS-ready register and the shelf map around shelves the owners would not move, training the staff, and delivering four and a half months of work against a three-month scope.`]})]}),(0,l.jsx)(`div`,{className:`dl-row`,style:{marginTop:20},children:(0,l.jsx)(o,{href:`index.html`,children:`← Back to home`})})]})}(0,s.createRoot)(document.getElementById(`root`)).render((0,l.jsx)(c.StrictMode,{children:(0,l.jsx)(m,{})}));